head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > getDataRow]<br/>Row 의 인덱스값을 사용하여 특정 Row 의 데이터를 Key-Value 쌍의 데이터 객체로 반환합니다.",
    "validation" : [        
        "rowIndex(필수) 파라미터로 반환 받으려는 Row 데이터의 인덱스값을 숫자로 설정합니다.",
        "Row 의 인덱스는 0 부터 시작하며 필터가 적용된 경우 필터링된 Row 를 기준으로 인덱스를 설정합니다.",
        "반환값으로 Row 의 상태값에 관계없이 파라미터에 해당하는 Row 의 데이터를 Key-Value 쌍의 데이터 객체로 반환합니다.",
        "반환되는 데이터 객체는 DataList 모듈의 전체 Column ID 를 Key 로 'Column ID:Value' 형태의 Key-Value 쌍으로 구성됩니다.",
        "파라미터에 해당하는 Row 가 없는 경우 전체 Column ID 의 Key 는 ''(Empty String) 값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}



scwin.btn_getDataRow_onclick = function (e) {
    let rowIndex = par_rowIndex.getText();
    let rtn = '';
    let rowCount = target1.getRowCount();

    if (rowIndex == "")
        rtn = target1.getDataRow();
    else
        rtn = target1.getDataRow(Number(rowIndex));

    for (var i=0; i < rowCount; i++) {
        let colKey = "col" + (i + 1);
        let cellValue = rtn[colKey];

        wf_body_bottom.getObj("scwin").setReturnValue(`row[${i}] : ${cellValue}`);
    }    
};



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})
    target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})
};
